window.DATA_PART=window.DATA_PART||{};window.DATA_PART["de-a1"]={"lectures":[{"id":"de-a1-L01","nr":1,"title":{"de":"Lektion 1: Hallo! Wer bist du?","en":"Lesson 1: Hello! Who are you?","tr":"Ders 1: Merhaba! Sen kimsin?"},"goals":{"de":["Ich kann jemanden begrüßen und mich verabschieden, im Kurs (du) und höflich (Sie).","Ich kann sagen, wie ich heiße, woher ich komme, wo ich wohne und welche Sprachen ich spreche.","Ich kann fragen, wie es jemandem geht, und darauf antworten.","Ich kann Dinge im Kursraum mit dem richtigen Artikel nennen (der, die, das, ein, eine)."],"en":["I can greet people and say goodbye, informally (du) and politely (Sie).","I can say my name, where I come from, where I live and which languages I speak.","I can ask how someone is and answer the question.","I can name things in the classroom with the correct article (der, die, das, ein, eine)."],"tr":["Birini selamlayabilir ve vedalaşabilirim; kursta samimi (du) ve resmî (Sie) olarak.","Adımı, nereden geldiğimi, nerede oturduğumu ve hangi dilleri konuştuğumu söyleyebilirim.","Birine nasıl olduğunu sorabilir ve bu soruya cevap verebilirim.","Sınıftaki eşyaları doğru artikelle söyleyebilirim (der, die, das, ein, eine)."]},"grammar":{"title":{"de":"Artikel: der, die, das – ein, eine","en":"Articles: der, die, das – ein, eine","tr":"Artikeller: der, die, das – ein, eine"},"explain":{"de":"Jedes Nomen hat im Deutschen ein Geschlecht: maskulin (der), feminin (die) oder neutral (das). Der Artikel steht vor dem Nomen. Im Plural heißt der bestimmte Artikel immer „die“. Der unbestimmte Artikel ist „ein“ (bei der und das) oder „eine“ (bei die); im Plural gibt es keinen unbestimmten Artikel. Nomen schreibst du immer groß. Das Geschlecht kannst du selten erraten, darum lernst du jedes Nomen mit Artikel und Plural: der Tisch, die Tische.","en":"Every German noun has a gender: masculine (der), feminine (die) or neuter (das). The article goes in front of the noun. In the plural the definite article is always “die”. The indefinite article is “ein” (for der and das nouns) or “eine” (for die nouns); there is no indefinite article in the plural. Nouns always start with a capital letter. You can rarely guess the gender, so learn every noun with its article and plural: der Tisch, die Tische.","tr":"Almancada her ismin bir cinsiyeti vardır: eril (der), dişil (die) ya da nötr (das). Türkçede artikel yoktur; Almancada artikel ismin önüne gelir. Çoğulda belirli artikel her zaman „die“ olur. Belirsiz artikel der ve das isimlerinde „ein“, die isimlerinde „eine“dir; çoğulda belirsiz artikel yoktur. İsimler her zaman büyük harfle yazılır. İsmin cinsiyetini tahmin etmek zordur, bu yüzden her ismi artikeli ve çoğuluyla birlikte öğren: der Tisch, die Tische."},"table":"<table class=\"tt\"><tr><th></th><th>bestimmt</th><th>unbestimmt</th><th>Beispiel</th></tr><tr><td>maskulin</td><td>der</td><td>ein</td><td>der Tisch / ein Tisch</td></tr><tr><td>feminin</td><td>die</td><td>eine</td><td>die Lampe / eine Lampe</td></tr><tr><td>neutral</td><td>das</td><td>ein</td><td>das Buch / ein Buch</td></tr><tr><td>Plural</td><td>die</td><td>–</td><td>die Tische / Tische</td></tr></table>","examples":[{"de":"Das ist ein Tisch. Der Tisch ist neu.","x":{"en":"This is a table. The table is new.","tr":"Bu bir masa. Masa yeni."}},{"de":"Das ist eine Lampe. Die Lampe ist schön.","x":{"en":"This is a lamp. The lamp is nice.","tr":"Bu bir lamba. Lamba güzel."}},{"de":"Das ist ein Buch. Das Buch ist dick.","x":{"en":"This is a book. The book is thick.","tr":"Bu bir kitap. Kitap kalın."}},{"de":"Das sind Stühle. Die Stühle sind alt.","x":{"en":"These are chairs. The chairs are old.","tr":"Bunlar sandalye. Sandalyeler eski."}}]},"vocab":[{"id":"de-a1-v0001","de":"der Name","art":"der","pl":"die Namen","x":{"en":"name","tr":"isim, ad"},"ex":"Mein Name ist Elif.","laut":"langes a: [ˈnaːmə]"},{"id":"de-a1-v0002","de":"der Vorname","art":"der","pl":"die Vornamen","x":{"en":"first name","tr":"ad (ilk ad)"},"ex":"Mein Vorname ist Can."},{"id":"de-a1-v0003","de":"der Familienname","art":"der","pl":"die Familiennamen","x":{"en":"last name, surname","tr":"soyadı"},"ex":"Mein Familienname ist Demir."},{"id":"de-a1-v0004","de":"das Land","art":"das","pl":"die Länder","x":{"en":"country","tr":"ülke"},"ex":"Das Land ist groß."},{"id":"de-a1-v0005","de":"die Stadt","art":"die","pl":"die Städte","x":{"en":"city, town","tr":"şehir"},"ex":"Köln ist eine Stadt.","laut":"st am Wortanfang: [ʃt]"},{"id":"de-a1-v0006","de":"die Sprache","art":"die","pl":"die Sprachen","x":{"en":"language","tr":"dil"},"ex":"Deutsch ist eine Sprache.","laut":"sp am Wortanfang: [ʃp], ch nach a: [x]"},{"id":"de-a1-v0007","de":"die Adresse","art":"die","pl":"die Adressen","x":{"en":"address","tr":"adres"},"ex":"Wie ist die Adresse?"},{"id":"de-a1-v0008","de":"die Straße","art":"die","pl":"die Straßen","x":{"en":"street","tr":"sokak, cadde"},"ex":"Die Straße ist lang.","laut":"ß wie scharfes s: [ˈʃtraːsə]"},{"id":"de-a1-v0009","de":"die Telefonnummer","art":"die","pl":"die Telefonnummern","x":{"en":"phone number","tr":"telefon numarası"},"ex":"Die Telefonnummer ist neu."},{"id":"de-a1-v0010","de":"der Mann","art":"der","pl":"die Männer","x":{"en":"man","tr":"adam, erkek"},"ex":"Der Mann heißt Jonas."},{"id":"de-a1-v0011","de":"die Frau","art":"die","pl":"die Frauen","x":{"en":"woman; Mrs","tr":"kadın; hanım"},"ex":"Die Frau heißt Elif."},{"id":"de-a1-v0012","de":"das Kind","art":"das","pl":"die Kinder","x":{"en":"child","tr":"çocuk"},"ex":"Das Kind heißt Mia."},{"id":"de-a1-v0013","de":"der Freund","art":"der","pl":"die Freunde","x":{"en":"friend (male)","tr":"arkadaş (erkek)"},"ex":"Das ist mein Freund Jonas.","laut":"eu: [ɔʏ]"},{"id":"de-a1-v0014","de":"die Freundin","art":"die","pl":"die Freundinnen","x":{"en":"friend (female)","tr":"arkadaş (kadın)"},"ex":"Das ist meine Freundin Elif.","laut":"eu: [ɔʏ]"},{"id":"de-a1-v0015","de":"der Herr","art":"der","pl":"die Herren","x":{"en":"Mr; gentleman","tr":"bay, beyefendi"},"ex":"Guten Tag, Herr Demir!"},{"id":"de-a1-v0016","de":"der Lehrer","art":"der","pl":"die Lehrer","x":{"en":"teacher (male)","tr":"öğretmen (erkek)"},"ex":"Der Lehrer kommt aus Berlin."},{"id":"de-a1-v0017","de":"die Lehrerin","art":"die","pl":"die Lehrerinnen","x":{"en":"teacher (female)","tr":"öğretmen (kadın)"},"ex":"Die Lehrerin heißt Frau Weber."},{"id":"de-a1-v0018","de":"der Kurs","art":"der","pl":"die Kurse","x":{"en":"course, class","tr":"kurs"},"ex":"Der Kurs ist gut."},{"id":"de-a1-v0019","de":"der Tisch","art":"der","pl":"die Tische","x":{"en":"table","tr":"masa"},"ex":"Der Tisch ist neu.","laut":"sch: [ʃ]"},{"id":"de-a1-v0020","de":"der Stuhl","art":"der","pl":"die Stühle","x":{"en":"chair","tr":"sandalye"},"ex":"Der Stuhl ist alt.","laut":"st am Wortanfang: [ʃt]"},{"id":"de-a1-v0021","de":"die Lampe","art":"die","pl":"die Lampen","x":{"en":"lamp","tr":"lamba"},"ex":"Die Lampe ist schön."},{"id":"de-a1-v0022","de":"das Buch","art":"das","pl":"die Bücher","x":{"en":"book","tr":"kitap"},"ex":"Das Buch ist dick.","laut":"ch nach u: [x]"},{"id":"de-a1-v0023","de":"das Heft","art":"das","pl":"die Hefte","x":{"en":"notebook, exercise book","tr":"defter"},"ex":"Das Heft ist rot."},{"id":"de-a1-v0024","de":"der Stift","art":"der","pl":"die Stifte","x":{"en":"pen","tr":"kalem"},"ex":"Der Stift ist blau.","laut":"st am Wortanfang: [ʃt]"},{"id":"de-a1-v0025","de":"die Tasche","art":"die","pl":"die Taschen","x":{"en":"bag","tr":"çanta"},"ex":"Die Tasche ist schwer.","laut":"sch: [ʃ]"},{"id":"de-a1-v0026","de":"das Handy","art":"das","pl":"die Handys","x":{"en":"mobile phone","tr":"cep telefonu"},"ex":"Das Handy ist kaputt.","laut":"gesprochen wie [ˈhɛndi]"},{"id":"de-a1-v0027","de":"das Wörterbuch","art":"das","pl":"die Wörterbücher","x":{"en":"dictionary","tr":"sözlük"},"ex":"Das Wörterbuch ist auf dem Tisch."},{"id":"de-a1-v0028","de":"die Tafel","art":"die","pl":"die Tafeln","x":{"en":"board (blackboard)","tr":"tahta (yazı tahtası)"},"ex":"Die Tafel ist groß."},{"id":"de-a1-v0029","de":"das Fenster","art":"das","pl":"die Fenster","x":{"en":"window","tr":"pencere"},"ex":"Das Fenster ist offen."},{"id":"de-a1-v0030","de":"die Tür","art":"die","pl":"die Türen","x":{"en":"door","tr":"kapı"},"ex":"Die Tür ist zu."},{"id":"de-a1-v0031","de":"Deutschland","art":null,"pl":null,"x":{"en":"Germany","tr":"Almanya"},"ex":"Jonas kommt aus Deutschland."},{"id":"de-a1-v0032","de":"die Türkei","art":"die","pl":null,"x":{"en":"Turkey (the country)","tr":"Türkiye"},"ex":"Elif kommt aus der Türkei."},{"id":"de-a1-v0033","de":"Deutsch","art":null,"pl":null,"x":{"en":"German (language)","tr":"Almanca"},"ex":"Ich lerne Deutsch."},{"id":"de-a1-v0034","de":"Türkisch","art":null,"pl":null,"x":{"en":"Turkish (language)","tr":"Türkçe"},"ex":"Elif spricht Türkisch."},{"id":"de-a1-v0035","de":"Englisch","art":null,"pl":null,"x":{"en":"English (language)","tr":"İngilizce"},"ex":"Sprichst du Englisch?","laut":"sch: [ʃ]"},{"id":"de-a1-v0036","de":"Hallo!","art":null,"pl":null,"x":{"en":"Hello! / Hi!","tr":"Merhaba!"},"ex":"Hallo, Jonas!"},{"id":"de-a1-v0037","de":"Guten Morgen!","art":null,"pl":null,"x":{"en":"Good morning!","tr":"Günaydın!"},"ex":"Guten Morgen, Frau Weber!"},{"id":"de-a1-v0038","de":"Guten Tag!","art":null,"pl":null,"x":{"en":"Hello! / Good day! (polite)","tr":"İyi günler! (resmî selam)"},"ex":"Guten Tag, Herr Demir!"},{"id":"de-a1-v0039","de":"Guten Abend!","art":null,"pl":null,"x":{"en":"Good evening!","tr":"İyi akşamlar!"},"ex":"Guten Abend, Elif!","laut":"Abend: am Ende [t], [ˈaːbn̩t]"},{"id":"de-a1-v0040","de":"Gute Nacht!","art":null,"pl":null,"x":{"en":"Good night!","tr":"İyi geceler!"},"ex":"Gute Nacht, Mia!","laut":"ch nach a: [x]"},{"id":"de-a1-v0041","de":"Tschüss!","art":null,"pl":null,"x":{"en":"Bye!","tr":"Hoşça kal! / Görüşürüz!"},"ex":"Tschüss, Jonas!","laut":"tsch: [tʃ], ü kurz: [tʃʏs]"},{"id":"de-a1-v0042","de":"Auf Wiedersehen!","art":null,"pl":null,"x":{"en":"Goodbye! (polite)","tr":"Hoşça kalın! (resmî)"},"ex":"Auf Wiedersehen, Frau Weber!","laut":"w: [v]"},{"id":"de-a1-v0043","de":"Wie geht's?","art":null,"pl":null,"x":{"en":"How are you?","tr":"Nasılsın?"},"ex":"Hallo, Elif! Wie geht's?"},{"id":"de-a1-v0044","de":"Danke!","art":null,"pl":null,"x":{"en":"Thank you!","tr":"Teşekkürler!"},"ex":"Danke, gut!"},{"id":"de-a1-v0045","de":"Bitte!","art":null,"pl":null,"x":{"en":"Please! / You're welcome!","tr":"Lütfen! / Rica ederim!"},"ex":"Danke! – Bitte!"},{"id":"de-a1-v0046","de":"Entschuldigung!","art":null,"pl":null,"x":{"en":"Excuse me! / Sorry!","tr":"Affedersiniz! / Pardon!"},"ex":"Entschuldigung, wie heißen Sie?","laut":"ch nach u: [x]"},{"id":"de-a1-v0047","de":"heißen","art":null,"pl":null,"x":{"en":"to be called","tr":"adı … olmak"},"ex":"Ich heiße Elif. (= Adım Elif.)","laut":"ei: [aɪ], ß: [s]"},{"id":"de-a1-v0048","de":"kommen (aus)","art":null,"pl":null,"x":{"en":"to come (from)","tr":"(bir yerden) gelmek"},"ex":"Ich komme aus der Türkei."},{"id":"de-a1-v0049","de":"wohnen (in)","art":null,"pl":null,"x":{"en":"to live (in)","tr":"(bir yerde) oturmak, yaşamak"},"ex":"Ich wohne in Aachen.","laut":"w: [v]"},{"id":"de-a1-v0050","de":"sprechen","art":null,"pl":null,"x":{"en":"to speak","tr":"konuşmak"},"ex":"Ich spreche Türkisch.","laut":"sp am Wortanfang: [ʃp], ch nach e: [ç]"},{"id":"de-a1-v0051","de":"sein","art":null,"pl":null,"x":{"en":"to be","tr":"olmak"},"ex":"Ich bin Elif. Du bist Jonas.","laut":"ei: [aɪ]"},{"id":"de-a1-v0052","de":"woher?","art":null,"pl":null,"x":{"en":"where from?","tr":"nereden?"},"ex":"Woher kommst du?","laut":"w: [v]"},{"id":"de-a1-v0053","de":"ja","art":null,"pl":null,"x":{"en":"yes","tr":"evet"},"ex":"Ja, ich spreche Deutsch."},{"id":"de-a1-v0054","de":"nein","art":null,"pl":null,"x":{"en":"no","tr":"hayır"},"ex":"Nein, ich spreche kein Englisch.","laut":"ei: [aɪ]"}],"dialogs":[{"id":"de-a1-L01-d1","title":{"de":"Im Kurs (du)","en":"In class (du)","tr":"Kursta (du)"},"lines":[["A","Hallo! Ich bin Elif. Wie heißt du?"],["B","Hallo, Elif! Ich heiße Jonas."],["A","Woher kommst du, Jonas?"],["B","Ich komme aus Deutschland, aus Köln. Und du?"],["A","Ich komme aus der Türkei. Ich wohne jetzt in Aachen."],["B","Sprichst du Englisch?"],["A","Ja, ich spreche Türkisch, Englisch und ein bisschen Deutsch."],["B","Super! Tschüss, Elif!"],["A","Tschüss!"]],"x":{"en":[["A","Hi! I'm Elif. What's your name?"],["B","Hi, Elif! My name is Jonas."],["A","Where are you from, Jonas?"],["B","I'm from Germany, from Cologne. And you?"],["A","I'm from Turkey. I live in Aachen now."],["B","Do you speak English?"],["A","Yes, I speak Turkish, English and a little German."],["B","Great! Bye, Elif!"],["A","Bye!"]],"tr":[["A","Merhaba! Ben Elif. Senin adın ne?"],["B","Merhaba Elif! Benim adım Jonas."],["A","Nerelisin Jonas?"],["B","Almanya'dan, Köln'den geliyorum. Ya sen?"],["A","Türkiye'den geliyorum. Şimdi Aachen'da oturuyorum."],["B","İngilizce konuşuyor musun?"],["A","Evet, Türkçe, İngilizce ve biraz Almanca konuşuyorum."],["B","Süper! Görüşürüz Elif!"],["A","Görüşürüz!"]]}},{"id":"de-a1-L01-d2","title":{"de":"Höflich (Sie)","en":"Polite (Sie)","tr":"Resmî (Sie)"},"lines":[["A","Guten Tag! Mein Name ist Demir, Can Demir."],["B","Guten Tag, Herr Demir. Ich bin Frau Weber, die Lehrerin."],["A","Freut mich, Frau Weber."],["B","Wie geht es Ihnen?"],["A","Danke, gut. Und Ihnen?"],["B","Auch gut, danke. Woher kommen Sie?"],["A","Ich komme aus der Türkei, aus Izmir."],["B","Und wo wohnen Sie?"],["A","In Aachen, in der Bahnhofstraße."],["B","Danke. Auf Wiedersehen, Herr Demir!"],["A","Auf Wiedersehen!"]],"x":{"en":[["A","Good afternoon! My name is Demir, Can Demir."],["B","Good afternoon, Mr Demir. I'm Ms Weber, the teacher."],["A","Nice to meet you, Ms Weber."],["B","How are you?"],["A","Fine, thank you. And you?"],["B","Fine too, thanks. Where are you from?"],["A","I'm from Turkey, from Izmir."],["B","And where do you live?"],["A","In Aachen, on Bahnhofstraße."],["B","Thank you. Goodbye, Mr Demir!"],["A","Goodbye!"]],"tr":[["A","İyi günler! Adım Demir, Can Demir."],["B","İyi günler Demir Bey. Ben Weber Hanım, öğretmeninizim."],["A","Memnun oldum Weber Hanım."],["B","Nasılsınız?"],["A","Teşekkürler, iyiyim. Ya siz?"],["B","Ben de iyiyim, teşekkürler. Nerelisiniz?"],["A","Türkiye'den, İzmir'den geliyorum."],["B","Peki nerede oturuyorsunuz?"],["A","Aachen'da, Bahnhofstraße'de."],["B","Teşekkürler. Hoşça kalın Demir Bey!"],["A","Hoşça kalın!"]]}}]}],"tasks":[{"id":"de-a1-L01-t01","lecture":"de-a1-L01","topic":"de-a1-L01-wort","level":1,"type":"mc","diag":true,"src":"eigene (Deutsch A1, Lektion 1)","q":{"de":"Es ist 20 Uhr. Wie begrüßt du jemanden?","en":"It is 8 p.m. How do you greet someone?","tr":"Saat 20.00. Birini nasıl selamlarsın?"},"x":{"de":"„Guten Abend!“ ist der Gruß am Abend. „Gute Nacht!“ sagst du erst, wenn jemand schlafen geht, und „Tschüss!“ ist ein Abschied.","en":"“Guten Abend!” is the evening greeting. You only say “Gute Nacht!” when someone goes to bed, and “Tschüss!” means goodbye.","tr":"„Guten Abend!“ akşam selamıdır. „Gute Nacht!“ ancak biri yatmaya giderken söylenir, „Tschüss!“ ise vedalaşmadır."},"options":["Guten Abend!","Gute Nacht!","Guten Morgen!","Tschüss!"],"correct":0},{"id":"de-a1-L01-t02","lecture":"de-a1-L01","topic":"de-a1-L01-wort","level":2,"type":"mc","diag":true,"src":"eigene (Deutsch A1, Lektion 1)","q":{"de":"Was ist der Plural von „das Buch“?","en":"What is the plural of “das Buch”?","tr":"„das Buch“ kelimesinin çoğulu nedir?"},"x":{"de":"Viele Nomen bekommen im Plural einen Umlaut und eine Endung: das Buch → die Bücher. Der Artikel im Plural ist immer „die“.","en":"Many nouns get an umlaut and an ending in the plural: das Buch → die Bücher. The plural article is always “die”.","tr":"Birçok isim çoğulda umlaut ve bir ek alır: das Buch → die Bücher. Çoğulda artikel her zaman „die“dir."},"options":["die Bücher","die Buchs","die Büchern","das Bücher"],"correct":0},{"id":"de-a1-L01-t03","lecture":"de-a1-L01","topic":"de-a1-L01-wort","level":3,"type":"cloze","diag":true,"src":"eigene (Deutsch A1, Lektion 1)","q":{"de":"Setze den Plural ein.","en":"Fill in the plural.","tr":"Çoğul hâlini yaz."},"x":{"de":"die Frau → die Frauen (Endung -en), der Mann → die Männer (Umlaut und -er). Nomen schreibst du groß.","en":"die Frau → die Frauen (ending -en), der Mann → die Männer (umlaut and -er). Nouns are written with a capital letter.","tr":"die Frau → die Frauen (-en eki), der Mann → die Männer (umlaut ve -er). İsimler büyük harfle yazılır."},"text":"Im Kurs sind zwei ___ (die Frau) und drei ___ (der Mann).","answers":[["Frauen"],["Männer"]]},{"id":"de-a1-L01-t04","lecture":"de-a1-L01","topic":"de-a1-L01-gram","level":1,"type":"mc","diag":true,"src":"eigene (Deutsch A1, Lektion 1)","q":{"de":"Welcher Artikel passt? „___ Lampe“","en":"Which article fits? “___ Lampe”","tr":"Hangi artikel uyar? „___ Lampe“"},"x":{"de":"Lampe ist feminin, darum „die Lampe“. Am besten lernst du das Wort gleich mit Artikel.","en":"Lampe is feminine, so it is “die Lampe”. Best learn the word together with its article.","tr":"Lampe dişildir, bu yüzden „die Lampe“. Kelimeyi en iyisi artikeliyle birlikte öğren."},"options":["die","der","das","den"],"correct":0},{"id":"de-a1-L01-t05","lecture":"de-a1-L01","topic":"de-a1-L01-gram","level":2,"type":"cloze","diag":true,"src":"eigene (Deutsch A1, Lektion 1)","q":{"de":"Ergänze erst den unbestimmten, dann den bestimmten Artikel.","en":"Fill in first the indefinite, then the definite article.","tr":"Önce belirsiz, sonra belirli artikeli yaz."},"x":{"de":"Neu im Gespräch: unbestimmter Artikel („ein Stuhl“). Danach ist er bekannt: bestimmter Artikel („der Stuhl“). Am Satzanfang groß: „Der“.","en":"New in the conversation: indefinite article (“ein Stuhl”). After that it is known: definite article (“der Stuhl”). At the start of a sentence: capital “Der”.","tr":"Konuşmada ilk kez geçince belirsiz artikel („ein Stuhl“). Sonra bilinen şey olur: belirli artikel („der Stuhl“). Cümle başında büyük harf: „Der“."},"text":"Das ist ___ Stuhl. ___ Stuhl ist neu.","answers":[["ein"],["Der"]]},{"id":"de-a1-L01-t06","lecture":"de-a1-L01","topic":"de-a1-L01-gram","level":3,"type":"cloze","diag":true,"src":"eigene (Deutsch A1, Lektion 1)","q":{"de":"Setze den unbestimmten Artikel ein: ein oder eine?","en":"Fill in the indefinite article: ein or eine?","tr":"Belirsiz artikeli yaz: ein mi, eine mi?"},"x":{"de":"die Tasche → eine Tasche, das Heft → ein Heft, der Stift → ein Stift. „eine“ nur bei femininen Nomen.","en":"die Tasche → eine Tasche, das Heft → ein Heft, der Stift → ein Stift. “eine” only with feminine nouns.","tr":"die Tasche → eine Tasche, das Heft → ein Heft, der Stift → ein Stift. „eine“ sadece dişil isimlerle."},"text":"Hier sind ___ Tasche, ___ Heft und ___ Stift.","answers":[["eine"],["ein"],["ein"]]},{"id":"de-a1-L01-t07","lecture":"de-a1-L01","topic":"de-a1-L01-komm","level":1,"type":"order","diag":true,"src":"eigene (Deutsch A1, Lektion 1)","q":{"de":"Bilde den Satz: Stell dich vor.","en":"Build the sentence: introduce yourself.","tr":"Cümleyi kur: kendini tanıt."},"x":{"de":"Im Aussagesatz steht das Verb an zweiter Stelle: Ich heiße Elif. Das Subjekt „Ich“ steht hier vorn.","en":"In a statement the verb is in second position: Ich heiße Elif. The subject “Ich” comes first here.","tr":"Düz cümlede fiil ikinci sıradadır: Ich heiße Elif. Burada özne „Ich“ başta."},"words":["heiße","Elif","Ich"],"answer":"Ich heiße Elif","alt":[]},{"id":"de-a1-L01-t08","lecture":"de-a1-L01","topic":"de-a1-L01-komm","level":2,"type":"dialog","diag":true,"src":"eigene (Deutsch A1, Lektion 1)","q":{"de":"Lies den Dialog „Im Kurs“ und beantworte die Fragen.","en":"Read the dialogue “In class” and answer the questions.","tr":"„Kursta“ diyaloğunu oku ve soruları cevapla."},"x":{"de":"Elif sagt: „Ich komme aus der Türkei.“ Jonas kommt aus Deutschland, genauer aus Köln.","en":"Elif says: “Ich komme aus der Türkei.” Jonas comes from Germany, from Cologne to be exact.","tr":"Elif „Ich komme aus der Türkei.“ diyor. Jonas Almanya'dan, tam olarak Köln'den geliyor."},"dialog":"de-a1-L01-d1","questions":[{"type":"mc","q":{"de":"Woher kommt Elif?","en":"Where is Elif from?","tr":"Elif nereli?"},"options":["aus der Türkei","aus Deutschland","aus Köln","aus Aachen"],"correct":0},{"type":"cloze","q":{"de":"Ergänze.","en":"Fill in.","tr":"Tamamla."},"text":"Jonas kommt aus ___.","answers":[["Deutschland","Köln"]]}]},{"id":"de-a1-L01-t09","lecture":"de-a1-L01","topic":"de-a1-L01-komm","level":3,"type":"mc","diag":true,"src":"eigene (Deutsch A1, Lektion 1)","q":{"de":"Du sprichst mit deiner Lehrerin, Frau Weber. Welche Frage passt?","en":"You are talking to your teacher, Ms Weber. Which question fits?","tr":"Öğretmenin Weber Hanım ile konuşuyorsun. Hangi soru uyar?"},"x":{"de":"Zu Erwachsenen, die du nicht gut kennst, sagst du höflich „Sie“: „Wie geht es Ihnen?“ Die anderen Fragen sind mit „du“.","en":"To adults you don't know well you use the polite “Sie”: “Wie geht es Ihnen?” The other questions use “du”.","tr":"İyi tanımadığın yetişkinlerle kibar „Sie“ kullanırsın: „Wie geht es Ihnen?“ Diğer sorular „du“ ile."},"options":["Wie geht es Ihnen?","Wie geht's dir?","Wie heißt du?","Woher kommst du?"],"correct":0},{"id":"de-a1-L01-t10","lecture":"de-a1-L01","topic":"de-a1-L01-wort","level":1,"type":"mc","diag":false,"src":"eigene (Deutsch A1, Lektion 1)","q":{"de":"Du gehst nach Hause. Was sagst du zu deinem Freund?","en":"You are going home. What do you say to your friend?","tr":"Eve gidiyorsun. Arkadaşına ne dersin?"},"x":{"de":"„Tschüss!“ ist der lockere Abschied unter Freunden. „Hallo!“ und „Guten Tag!“ sind Begrüßungen.","en":"“Tschüss!” is the casual goodbye between friends. “Hallo!” and “Guten Tag!” are greetings.","tr":"„Tschüss!“ arkadaşlar arasında samimi vedalaşmadır. „Hallo!“ ve „Guten Tag!“ selamlaşmadır."},"options":["Tschüss!","Hallo!","Guten Tag!","Danke!"],"correct":0},{"id":"de-a1-L01-t11","lecture":"de-a1-L01","topic":"de-a1-L01-komm","level":1,"type":"cloze","diag":false,"src":"eigene (Deutsch A1, Lektion 1)","q":{"de":"Setze das Verb in der richtigen Form ein.","en":"Fill in the verb in the correct form.","tr":"Fiili doğru biçimde yaz."},"x":{"de":"heißen: ich heiße, du heißt. Bei „ich“ endet das Verb auf -e.","en":"heißen: ich heiße, du heißt. With “ich” the verb ends in -e.","tr":"heißen: ich heiße, du heißt. „ich“ ile fiil -e ile biter."},"text":"Ich ___ Elif. (heißen)","answers":[["heiße"]]},{"id":"de-a1-L01-t12","lecture":"de-a1-L01","topic":"de-a1-L01-gram","level":2,"type":"cloze","diag":false,"src":"eigene (Deutsch A1, Lektion 1)","q":{"de":"Ergänze die bestimmten Artikel.","en":"Fill in the definite articles.","tr":"Belirli artikelleri tamamla."},"x":{"de":"das Buch (neutral), die Lampe (feminin). Am Satzanfang groß.","en":"das Buch (neuter), die Lampe (feminine). Capital letter at the start of a sentence.","tr":"das Buch (nötr), die Lampe (dişil). Cümle başında büyük harf."},"text":"___ Buch ist neu. ___ Lampe ist alt.","answers":[["Das"],["Die"]]},{"id":"de-a1-L01-t13","lecture":"de-a1-L01","topic":"de-a1-L01-komm","level":2,"type":"order","diag":false,"src":"eigene (Deutsch A1, Lektion 1)","q":{"de":"Bilde die Frage.","en":"Build the question.","tr":"Soruyu kur."},"x":{"de":"In der W-Frage steht das Fragewort vorn, dann das Verb: Woher kommst du?","en":"In a question-word question the question word comes first, then the verb: Woher kommst du?","tr":"Soru kelimeli soruda soru kelimesi başta, sonra fiil gelir: Woher kommst du?"},"words":["kommst","du","Woher"],"answer":"Woher kommst du","alt":[]},{"id":"de-a1-L01-t14","lecture":"de-a1-L01","topic":"de-a1-L01-komm","level":2,"type":"cloze","diag":false,"src":"eigene (Deutsch A1, Lektion 1)","q":{"de":"Ergänze das Verb „kommen“.","en":"Fill in the verb “kommen”.","tr":"„kommen“ fiilini tamamla."},"x":{"de":"du kommst, ich komme. Die Endung zeigt, wer spricht.","en":"du kommst, ich komme. The ending shows who is speaking.","tr":"du kommst, ich komme. Ek, kimin konuştuğunu gösterir."},"text":"Woher ___ du? – Ich ___ aus der Türkei.","answers":[["kommst"],["komme"]]},{"id":"de-a1-L01-t15","lecture":"de-a1-L01","topic":"de-a1-L01-gram","level":2,"type":"mc","diag":false,"src":"eigene (Deutsch A1, Lektion 1)","q":{"de":"Welcher Satz ist richtig geschrieben?","en":"Which sentence is spelled correctly?","tr":"Hangi cümle doğru yazılmış?"},"x":{"de":"Nomen (Tisch) und das erste Wort im Satz schreibst du groß, Verben (ist) und Artikel im Satz klein.","en":"Nouns (Tisch) and the first word of a sentence are capitalised; verbs (ist) and articles inside the sentence are not.","tr":"İsimler (Tisch) ve cümlenin ilk kelimesi büyük harfle; fiiller (ist) ve cümle içindeki artikeller küçük harfle yazılır."},"options":["Das ist ein Tisch.","Das ist ein tisch.","das ist Ein Tisch.","Das Ist ein Tisch."],"correct":0},{"id":"de-a1-L01-t16","lecture":"de-a1-L01","topic":"de-a1-L01-komm","level":3,"type":"order","diag":false,"src":"eigene (Deutsch A1, Lektion 1)","q":{"de":"Bilde die höfliche Frage.","en":"Build the polite question.","tr":"Kibar soruyu kur."},"x":{"de":"Wie geht es Ihnen? Das Fragewort steht vorn, das Verb an zweiter Stelle. „Ihnen“ ist die höfliche Form.","en":"Wie geht es Ihnen? The question word comes first, the verb second. “Ihnen” is the polite form.","tr":"Wie geht es Ihnen? Soru kelimesi başta, fiil ikinci sırada. „Ihnen“ kibar biçimdir."},"words":["es","Ihnen","Wie","geht"],"answer":"Wie geht es Ihnen","alt":[]},{"id":"de-a1-L01-t17","lecture":"de-a1-L01","topic":"de-a1-L01-komm","level":2,"type":"dialog","diag":false,"src":"eigene (Deutsch A1, Lektion 1)","q":{"de":"Lies den Dialog „Höflich“ und beantworte die Fragen.","en":"Read the dialogue “Polite” and answer the questions.","tr":"„Resmî“ diyaloğunu oku ve soruları cevapla."},"x":{"de":"Frau Weber ist die Lehrerin. Herr Demir kommt aus Izmir und wohnt jetzt in Aachen.","en":"Ms Weber is the teacher. Mr Demir comes from Izmir and now lives in Aachen.","tr":"Weber Hanım öğretmen. Demir Bey İzmirli ve şimdi Aachen'da oturuyor."},"dialog":"de-a1-L01-d2","questions":[{"type":"mc","q":{"de":"Wer ist die Lehrerin?","en":"Who is the teacher?","tr":"Öğretmen kim?"},"options":["Frau Weber","Herr Demir","Elif","Jonas"],"correct":0},{"type":"mc","q":{"de":"Wo wohnt Herr Demir?","en":"Where does Mr Demir live?","tr":"Demir Bey nerede oturuyor?"},"options":["in Aachen","in Izmir","in Köln","in der Türkei"],"correct":0}]},{"id":"de-a1-L01-t18","lecture":"de-a1-L01","topic":"de-a1-L01-komm","level":3,"type":"dialog","diag":false,"src":"eigene (Deutsch A1, Lektion 1)","q":{"de":"Ergänze die höfliche Antwort aus dem Dialog.","en":"Complete the polite answer from the dialogue.","tr":"Diyalogdaki kibar cevabı tamamla."},"x":{"de":"Bei „Sie“ fragst du zurück: „Und Ihnen?“ Mit „du“ hieße es: „Und dir?“","en":"With “Sie” you ask back: “Und Ihnen?” With “du” it would be: “Und dir?”","tr":"„Sie“ ile karşı soru: „Und Ihnen?“ „du“ ile: „Und dir?“"},"dialog":"de-a1-L01-d2","questions":[{"type":"cloze","q":{"de":"Ergänze.","en":"Fill in.","tr":"Tamamla."},"text":"Herr Demir: „Danke, gut. Und ___?“","answers":[["Ihnen"]]}]},{"id":"de-a1-L01-t19","lecture":"de-a1-L01","topic":"de-a1-L01-wort","level":1,"type":"mc","diag":false,"src":"eigene (Deutsch A1, Lektion 1)","q":{"de":"Welches Wort bedeutet „table“?","en":"Which word means “table”?","tr":"Hangi kelime „masa“ demek?"},"x":{"de":"der Tisch = table / masa. der Stuhl = chair / sandalye, die Tafel = board / tahta, das Fenster = window / pencere.","en":"der Tisch = table. der Stuhl = chair, die Tafel = board, das Fenster = window.","tr":"der Tisch = masa. der Stuhl = sandalye, die Tafel = tahta, das Fenster = pencere."},"options":["der Tisch","der Stuhl","die Tafel","das Fenster"],"correct":0},{"id":"de-a1-L01-t20","lecture":"de-a1-L01","topic":"de-a1-L01-wort","level":3,"type":"cloze","diag":false,"src":"eigene (Deutsch A1, Lektion 1)","q":{"de":"Setze den Plural ein.","en":"Fill in the plural.","tr":"Çoğul hâlini yaz."},"x":{"de":"das Buch → die Bücher, der Stift → die Stifte. Jedes Nomen hat seine eigene Pluralform, darum lernst du sie mit.","en":"das Buch → die Bücher, der Stift → die Stifte. Every noun has its own plural, so learn it together with the noun.","tr":"das Buch → die Bücher, der Stift → die Stifte. Her ismin kendi çoğul biçimi vardır, bu yüzden onu da birlikte öğren."},"text":"Das sind zwei ___ (das Buch) und drei ___ (der Stift).","answers":[["Bücher"],["Stifte"]]}],"formulas":[]};